#' Set outlier critical value
#'
#' Set outlier critical value using the Ljung algorithm as given in
#' \insertCite{Ljung93;textual}{sautilities}.
#' 
#' Version 2.0, 2026-03-04
#'
#' @param number_observations Integer scalar; number of observations tested   
#'        for outliers. This is a required entry.
#' @param cv_alpha Numeric scalar; alpha for critical value.
#'        Default is \code{0.01}.
#' @return Outlier critical value generated by the algorithm given in 
#'         \insertCite{Ljung93;textual}{sautilities}. The critical value in 
#'         X-13ARIMA-SEATS is different as it is adjusted to allow for  
#'         smaller values to approximate the normal distribution.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' this_critical_value <- set_critical_value(12, 0.025)
#' @importFrom Rdpack reprompt
#' @export
set_critical_value <- 
   function(number_observations = NULL, cv_alpha = 0.01) {
    # Author: Brian C. Monsell (OEUS) Version 2.0, 2026-03-04
    
    # check if a value is specified for \code{number_observations}
    if (is.null(number_observations)) {
        stop("must specify number of observations.")
    }

    pmod <- 2 - sqrt(1 + cv_alpha)
    acv <- sqrt(2 * log(number_observations))
    bcv <- acv - (log(log(number_observations)) + log(2 * 2 * pi))/(2 * acv)
    xcv <- -log(-0.5 * log(pmod))
    setcvl <- (xcv/acv) + bcv
    return(setcvl)
}
